/* Авторские задачи ЕГЭ по электрическому полю и постоянному току. */
(() => {
  const electrostatics = 356;
  const circuits = 241;
  const variants = [
    [electrostatics, 'Сила в однородном поле', 'мН', n => [
      `На частицу с зарядом ${n} мкКл действует однородное электрическое поле напряжённостью 4 кВ/м. Найди модуль силы в мН.`, 4*n,
      'Для положительного заряда модуль силы равен qE.',
      `1 мкКл · 1 кВ/м = 1 мН, поэтому F = ${n} · 4 = ${4*n} мН.`
    ]],
    [electrostatics, 'Закон Кулона', 'мН', n => [
      `Два точечных заряда ${n} нКл и 40 нКл находятся в вакууме на расстоянии 3 см. Найди модуль силы взаимодействия в мН. Прими k = 9·10⁹ Н·м²/Кл².`, 0.4*n,
      'Используй F = k|q₁q₂|/r² и переведи данные в СИ.',
      `F = 9·10⁹ · (${n}·10⁻⁹) · (40·10⁻⁹)/(0,03)² = ${Number((0.4*n).toFixed(1))} мН.`
    ]],
    [electrostatics, 'Работа электрического поля', 'мкДж', n => [
      `Заряд +${n} мкКл переносится из точки с потенциалом 70 В в точку с потенциалом 25 В. Какую работу в мкДж совершает поле?`, 45*n,
      'Работа поля равна q(φ₁ − φ₂).',
      `Разность потенциалов равна 45 В, поэтому A = ${n} · 45 = ${45*n} мкДж.`
    ]],
    [electrostatics, 'Энергия конденсатора', 'мкДж', n => [
      `Конденсатор ёмкостью ${2*n} мкФ зарядили до 30 В и отключили от источника. Какую энергию в мкДж он запас?`, 900*n,
      'Энергия заряженного конденсатора равна CU²/2.',
      `W = ${2*n} · 30²/2 = ${900*n} мкДж, поскольку 1 мкФ·В² = 1 мкДж.`
    ]],
    [electrostatics, 'Ускорение заряженной частицы', 'эВ', n => [
      `В вакууме электрон разгоняется полем из состояния покоя и попадает в точку с потенциалом на ${25*n} В выше начального. Найди конечную кинетическую энергию в эВ.`, 25*n,
      'Прирост кинетической энергии равен работе поля. Для электрона q = −e.',
      `При увеличении потенциала на Δφ работа A = eΔφ. Значит, K = ${25*n} эВ.`
    ]],
    [circuits, 'Последовательное соединение', 'В', n => [
      `Резисторы ${n} Ом и ${2*n} Ом последовательно подключены к идеальному источнику напряжения ${9*n} В. Найди напряжение на резисторе меньшего сопротивления.`, 3*n,
      `Полное сопротивление равно ${3*n} Ом, поэтому ток в обоих резисторах равен ${9*n}/${3*n} = 3 А.`,
      `На меньшем резисторе U = IR = 3 · ${n} = ${3*n} В.`
    ]],
    [circuits, 'Две параллельные ветви', 'А', n => [
      `Резисторы 6 Ом и 12 Ом подключены параллельно к источнику напряжения ${4*n} В. Найди общий ток в амперах.`, n,
      'Обе ветви находятся под одним напряжением, а общий ток равен сумме токов в ветвях.',
      `I = U(1/6 + 1/12) = ${4*n}/4 = ${n} А.`
    ]],
    [circuits, 'Источник с внутренним сопротивлением', 'В', n => [
      `Источник с ЭДС ${5*n} В и внутренним сопротивлением 2 Ом подключён к резистору 8 Ом. Найди напряжение на зажимах источника в вольтах.`, 4*n,
      `С учётом внутреннего сопротивления ток I = ε/(R + r) = ${5*n}/10 = ${n/2} А.`,
      `Напряжение на зажимах равно напряжению на резисторе: U = IR = ${n/2} · 8 = ${4*n} В.`
    ]],
    [circuits, 'Нагрев проводника', 'кДж', n => [
      `Через нагреватель сопротивлением 25 Ом течёт постоянный ток 2 А. Сколько килоджоулей теплоты выделится за ${10*n} с?`, n,
      'По закону Джоуля — Ленца мощность нагрева P = I²R.',
      `P = 2² · 25 = 100 Вт. За указанное время Q = 100 · ${10*n} = ${1000*n} Дж = ${n} кДж.`
    ]],
    [circuits, 'Перемещение заряда в цепи', 'Кл', n => [
      `Через резистор 10 Ом за ${n} секунд выделилось ${40*n} Дж теплоты. Какой заряд прошёл через него, если ток постоянный?`, 2*n,
      `Мощность нагрева P = Q/t = 40 Вт. Из P = I²R следует I = √(40/10) = 2 А.`,
      `Прошедший заряд q = It = 2 · ${n} = ${2*n} Кл.`
    ]]
  ];

  for (const [index, [category, title, unit, build]] of variants.entries()) {
    for (let variant = 1; variant <= 15; variant++) {
      const [question, rawAnswer, ...steps] = build(variant + 1);
      const answer = Number(rawAnswer.toFixed(5));
      tasks.push({
        id: `ege-physics-electricity-${index + 1}-${variant}`,
        grade: 11,
        domain: 'physics',
        subject: 'physics',
        exam: 'ege',
        topic: 0,
        topicName: 'Электрическое поле и постоянный ток',
        examTopic: 'physics-ege-electricity',
        level: [4, 7, 9].includes(index) ? 2 : 1,
        title, question, answer, unit, steps,
        hints: ['Определи, какая физическая величина связывает данные с искомым ответом.'],
        solution: steps.join(' '),
        review: {plan: steps[0]},
        source: {
          name: 'Решу ЕГЭ',
          id: category,
          type: 'тематический каталог',
          url: `https://phys-ege.sdamgia.ru/test?category_id=${category}&filter=all`,
          note: 'Авторская задача МатКлуба. По ссылке доступна дополнительная практика по теме.'
        }
      });
    }
  }
})();

